package domus;
import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

import casas.Casa;

public class App {
    public String getGreeting() {
        return "Hello World!";
    }

    


    public static Casa casaMaisConsumo(List<Casa> casas) {
        if (casas == null || casas.isEmpty()) return null;
        return casas.stream()
                    .max(Comparator.comparingDouble(Casa::calcularConsumoTotal))
                    .orElse(null);
    }

}
